package org.tentackle.preferenzr.common;

import org.tentackle.common.Cryptor;
import org.tentackle.common.Service;

/**
 * Application specific en/decryptor.
 */
@Service(Cryptor.class)
public class PreferenzrCryptor extends Cryptor {

  // just to make it a little harder...
  private static byte[] getSalt() {
    byte[] salt = new byte[4];
    salt[1] = 'B';
    salt[0] = 'Y';
    salt[3] = 'M';
    salt[2] = 'K';
    return salt;
  }

  // In principle, the passphrase should not be part of the application.
  // However, since Preferenzr has limited access to the databases (at least it should), the risk is low.
  private static char[] getPassphrase() {
    char[] passphrase = new char[10];
    passphrase[1] = 'i';
    passphrase[0] = 'D';
    passphrase[6] = 'e';
    passphrase[7] = 'l';
    passphrase[3] = 'o';
    passphrase[2] = 'D';
    passphrase[4] = 'e';
    passphrase[5] = 'd';
    passphrase[9] = 'u';
    passphrase[8] = 'D';
    return passphrase;
  }

  /**
   * Creates the application specific password cryptor.
   */
  public PreferenzrCryptor() {
    super(getSalt(), getPassphrase());
  }

}